window.CATALOGUE = [{"id": "OBJ-0001", "designation": "Chevalière armoriée Montferrand–Pellegrue", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0001_sceau_Montferrand_Pellegrue.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0001.jpg", "vignette": null, "nature": ["Bagues"], "dimensions": "", "poids": "", "dateMin": 1800, "dateMax": 1900, "datation": "XIXe siècle probable", "epoque": ["Époque contemporaine"], "culture": [], "aireGeographique": ["France", "Cancon"], "materiauxMetalliques": [], "materiauxNonMetalliques": [], "technique": [], "decor": ["Héraldique"], "fonctionUsage": [], "particularites": "Chevalière à matrice gravée en creux montrant deux écus d’alliance accolés sous une couronne nobiliaire et entourés d’ornements. Deux animaux tenants, vraisemblablement des lions, encadrent l’ensemble. L’écu de gauche porte les armes Montferrand de Guyenne ; celui de droite une grue tenant sa vigilance pour Pellegrue. Petite marque en losange à l’intérieur de l’anneau et zone centrale de fixation ou de soudure au revers du plateau.", "usageTexte": "Cette chevalière porte des armes d’alliance et constitue à la fois un bijou héraldique et une matrice sigillaire. Le décor gravé en creux est conçu pour produire une empreinte lisible dans la cire.", "texteAnalyse": "L’écu de gauche correspond aux armes des Montferrand de Guyenne ; celui de droite porte la grue tenant sa vigilance des Pellegrue. La réunion de ces deux armes correspond au mariage de François II de Montferrand et de Claire de Pellegrue, célébré à Cancon en 1577.\n\nLa gravure utilise les hachures conventionnelles de l’héraldique moderne, diffusées à partir des années 1630. La petite marque en losange visible à l’intérieur de l’anneau est compatible avec un poinçon de maître français postérieur à 1797. Le plateau paraît en outre rapporté sur la structure de l’anneau, avec une zone de fixation ou de soudure au revers.\n\nLes armes d’alliance Montferrand–Pellegrue sont solidement identifiées, mais la chevalière actuellement conservée n’est vraisemblablement pas le bijou personnel du couple au XVIe siècle. L’ensemble paraît avoir été fabriqué ou remonté plus tard, probablement au XIXe siècle. Un plateau plus ancien remonté sur un anneau récent reste possible, mais aucun indice ne permet actuellement de l’établir."}, {"id": "OBJ-0002", "designation": "Fibule dragonesque émaillée", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0002_Fibule_dragonesque.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0002.jpg", "vignette": null, "nature": ["Fibules"], "dimensions": "Environ 5 x 3 cm", "poids": "", "dateMin": 75, "dateMax": 175, "datation": "Bretagne romaine, environ 75–175", "epoque": ["Antiquité"], "culture": ["Romaine"], "aireGeographique": ["Angleterre", "Bretagne romaine"], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": ["Émail"], "technique": ["Moulé", "Émaillé", "Champlevé"], "decor": ["Zoomorphe"], "fonctionUsage": ["Vie quotidienne"], "particularites": "Plaque plate dessinant un S, terminée par deux têtes animales opposées avec de grands appendices comparables à des oreilles et des museaux recourbés. La face porte des cellules circulaires avec des restes d’émail rouges ou orangés, bleus et turquoise. Au revers, l’épingle s’enroule autour d’un rétrécissement du corps. Son aspect plus sombre et régulier que celui du corps suggère une restauration ou un remplacement moderne probable.", "usageTexte": "Cette fibule servait à maintenir un vêtement. Son système d’épingle enroulée autour du corps est caractéristique des fibules dragonesques. La robustesse habituelle de ce type d’attache convient notamment à des étoffes relativement épaisses.", "texteAnalyse": "La forme générale en S terminée par deux têtes animales opposées est caractéristique des fibules dragonesques. Les cavités de la face étaient destinées à recevoir de l’émail champlevé. La disposition en cellules circulaires permet d’envisager un groupe décoratif à motifs circulaires, sans retenir un sous-type plus précis.\n\nLa fibule dragonesque est caractéristique de la Bretagne romaine. Elle conserve un vocabulaire décoratif d’inspiration celtique insulaire tout en appartenant à la période romaine postérieure à la conquête. Une datation d’environ 75 à 175 apr. J.-C. est retenue. Il ne s’agit donc pas d’une fibule gauloise de l’âge du Fer, mais d’un objet romano-britannique.\n\nLe corps, sa patine et ses concrétions sont compatibles avec un objet ancien. L’épingle contraste par son aspect sombre et régulier et paraît vraisemblablement restaurée ou remplacée. Les émaux conservés sont cohérents avec le type, mais d’éventuelles retouches modernes ne peuvent pas être exclues sur les seules photographies."}, {"id": "OBJ-0003", "designation": "Fibule discoïdale émaillée", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0003_fibule_gallo-romaine.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0003.jpg", "vignette": null, "nature": ["Fibules"], "dimensions": "Diamètre environ 3 cm", "poids": "", "dateMin": 100, "dateMax": 250, "datation": "Époque romaine, probablement IIe siècle", "epoque": ["Antiquité"], "culture": ["Gallo-romaine"], "aireGeographique": ["Gaule"], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": ["Émail"], "technique": ["Émaillé"], "decor": ["Géométrique"], "fonctionUsage": ["Vie quotidienne"], "particularites": "Fibule en disque à décor concentrique, avec bosse centrale et compartiments radiaux conservant des traces d’émail orange et sombre. Le revers conserve la charnière et le porte-ardillon ; l’ardillon est perdu.", "usageTexte": "Cette fibule se portait sur le vêtement. L’ardillon traversait le tissu puis venait se bloquer dans le porte-ardillon. Elle associait ainsi une fonction de fermeture à une fonction de parure grâce à son décor émaillé.", "texteAnalyse": "La forme discoïdale, la bosse centrale et les compartiments émaillés permettent une identification solide comme fibule romaine. L’appellation de fibule umbonée est plausible pour le sous-type, mais reste volontairement prudente.\n\nLa fourchette 100-250 apr. J.-C. est retenue, avec une probabilité plus forte pour le IIe siècle.\n\nLes éléments du système de fixation restent lisibles au revers : charnière et porte-ardillon sont conservés, tandis que l’ardillon est perdu."}, {"id": "OBJ-0004", "designation": "Plaque de boucle / garniture de ceinture à décor d’ocelles, probable", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0004_Plaque de boucle : garniture de ceinture à décor d'ocelles.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0004.jpg", "vignette": null, "nature": ["Parures vestimentaires"], "dimensions": "Environ 4 x 4 cm", "poids": "", "dateMin": 550, "dateMax": 750, "datation": "Haut Moyen Âge, environ 550-750, datation de travail", "epoque": ["Haut Moyen Âge"], "culture": [], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Moulé", "Poinçonné", "Incisé"], "decor": ["Géométrique"], "fonctionUsage": ["Vie quotidienne"], "particularites": "Plaque semi-circulaire en alliage cuivreux, épaisse et légèrement bombée, ornée de plusieurs ocelles ou cercles concentriques pointés régulièrement répartis sur la face. Le revers comporte des éléments saillants de fixation, dont une patte perforée, compatibles avec un système d’articulation ou de montage sur une ceinture ou une courroie.", "usageTexte": "L’objet est probablement une plaque de boucle ou une garniture de ceinture. La partie perforée pouvait recevoir un axe ou un élément articulé aujourd’hui disparu. Le décor d’ocelles participait également à l’ornementation de la ceinture.", "texteAnalyse": "La forme semi-circulaire, l’épaisseur de la plaque et surtout les reliefs de fixation observés au revers indiquent que l’objet était destiné à être monté ou articulé sur un autre élément. La présence d’une patte perforée oriente vers une plaque de boucle ou une garniture articulée de ceinture plutôt que vers une fibule ou une simple applique.\n\nLes garnitures de ceinture en alliage cuivreux à pattes de fixation et décor de cercles pointés sont bien attestées au haut Moyen Âge. Une fourchette de travail d’environ 550 à 750 est retenue, volontairement large.\n\nDes comparaisons existent parmi les garnitures byzantines et méditerranéennes des VIe-VIIe siècles. Cette piste est plausible, mais l’absence de provenance et de parallèle strictement identique ne permet pas de retenir une attribution culturelle certaine."}, {"id": "OBJ-0005", "designation": "Fibule discoïdale émaillée à bosse centrale", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0005_fibule_discoidale_emaillee.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0005.jpg", "vignette": null, "nature": ["Fibules"], "dimensions": "Environ 3,5 cm", "poids": "", "dateMin": 100, "dateMax": 250, "datation": "Époque romaine, probablement IIe siècle", "epoque": ["Antiquité"], "culture": ["Gallo-romaine"], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": ["Émail"], "technique": ["Émaillé"], "decor": ["Géométrique"], "fonctionUsage": ["Vie quotidienne"], "particularites": "Disque circulaire muni de plusieurs appendices périphériques. La face est organisée en cercles concentriques autour d’une bosse centrale très saillante. Des restes d’émail bleu et des traces rouges et claires sont visibles. Le revers conserve des reliefs compatibles avec l’ancien système de fixation.", "usageTexte": "Cette fibule servait à maintenir un vêtement grâce à son ardillon, tout en constituant un élément de parure visible. Son décor émaillé renforçait sa fonction ornementale.", "texteAnalyse": "La morphologie discoïdale, la forte bosse centrale et le décor émaillé permettent de rattacher l’objet aux fibules romaines discoïdales. Le terme « umbonée » est plausible pour préciser le sous-type, mais reste une hypothèse prudente.\n\nLa morphologie et le décor émaillé orientent vers une production romaine, probablement du IIe siècle. Une fourchette de travail de 100 à 250 apr. J.-C. est conservée.\n\nLe revers présente encore des reliefs compatibles avec l’ancien système de fixation de l’ardillon."}, {"id": "OBJ-0006", "designation": "Fibule-plaque symétrique émaillée", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0006_fibule_plaque_symetrique_emaillee.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0006.jpg", "vignette": null, "nature": ["Fibules"], "dimensions": "Environ 4,5 x 1,6 cm", "poids": "", "dateMin": 100, "dateMax": 300, "datation": "Époque romaine, probablement IIe–IIIe siècle", "epoque": ["Antiquité"], "culture": ["Romaine"], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": ["Émail"], "technique": ["Émaillé"], "decor": ["Géométrique"], "fonctionUsage": ["Vie quotidienne"], "particularites": "Petite fibule-plaque symétrique à partie centrale rectangulaire. Le décor géométrique est composé de compartiments triangulaires avec des restes d’émail. De part et d’autre, des prolongements moulurés se terminent par des appendices arrondis. Le système d’attache au revers est incomplet.", "usageTexte": "Cette fibule servait à fixer ou retenir une partie du vêtement. Sa plaque émaillée, visible une fois portée, constituait également un élément de parure.", "texteAnalyse": "La plaque centrale rectangulaire, les extrémités symétriques et le système d’attache permettent d’identifier une fibule-plaque romaine émaillée.\n\nLa combinaison du décor géométrique compartimenté, de l’émail et de la construction de la fibule conduit à retenir une datation de travail de 100 à 300 apr. J.-C., avec une probabilité plus forte pour les IIe-IIIe siècles.\n\nLa désignation reste volontairement descriptive. Aucun sous-type plus précis n’est retenu faute de parallèle typologique suffisamment proche."}, {"id": "OBJ-0007", "designation": "Fibule-plaque rectangulaire émaillée à extrémités symétriques", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0007_fibule_plaque_rectangulaire_emaillee.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0007.jpg", "vignette": null, "nature": ["Fibules"], "dimensions": "3 x 1,6 cm", "poids": "", "dateMin": 100, "dateMax": 300, "datation": "Époque romaine, probablement IIe–IIIe siècle", "epoque": ["Antiquité"], "culture": ["Romaine"], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": ["Émail"], "technique": ["Émaillé"], "decor": ["Géométrique"], "fonctionUsage": ["Vie quotidienne"], "particularites": "Petite fibule-plaque symétrique autour d’une plaque centrale rectangulaire légèrement bombée. La face porte un décor compartimenté avec des restes d’émail rouge et verdâtre. Les extrémités latérales sont moulurées et symétriques. Le système d’attache au revers est incomplet.", "usageTexte": "Portée sur le vêtement, cette fibule assurait une fixation tout en présentant sur la face visible un petit décor coloré en émail.", "texteAnalyse": "La plaque rectangulaire légèrement bombée, les extrémités moulurées symétriques et les vestiges du système d’attache permettent d’identifier une fibule romaine émaillée.\n\nLa plaque émaillée compartimentée et la construction du système de fixation orientent vers une datation de 100 à 300 apr. J.-C., avec une probabilité plus forte pour les IIe-IIIe siècles.\n\nLa désignation reste descriptive. Aucun sous-type plus précis n’est retenu sans parallèle strictement comparable."}, {"id": "OBJ-0008", "designation": "Fibule-plaque rectangulaire émaillée à décor de losanges", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0008_fibule_plaque_rectangulaire_emaillee_losanges.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0008.jpg", "vignette": null, "nature": ["Fibules"], "dimensions": "3 x 1,4 cm", "poids": "", "dateMin": 100, "dateMax": 300, "datation": "Époque romaine, probablement IIe–IIIe siècle", "epoque": ["Antiquité"], "culture": ["Romaine"], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": ["Émail"], "technique": ["Émaillé"], "decor": ["Géométrique"], "fonctionUsage": ["Vie quotidienne"], "particularites": "Petite fibule-plaque allongée centrée sur une plaque rectangulaire. La face présente une rangée de motifs en losange ou étoilés avec des restes d’émail clair et rouge. Le décor est encadré par des moulures longitudinales. Le système d’attache au revers est incomplet.", "usageTexte": "Cette fibule se fixait au vêtement au moyen de son ardillon. La petite plaque décorée d’émail constituait la partie visible et ornementale.", "texteAnalyse": "La forme allongée, la plaque centrale rectangulaire, le décor compartimenté et les vestiges du système d’attache permettent d’identifier une fibule romaine émaillée.\n\nLa construction et le décor émaillé conduisent à conserver une fourchette de travail de 100 à 300 apr. J.-C., avec une probabilité plus forte pour les IIe-IIIe siècles.\n\nLes motifs en losange ou étoilés caractérisent le décor de cet exemplaire, mais aucun sous-type typologique plus précis n’est retenu."}, {"id": "OBJ-0009", "designation": "Fibule-plaque rectangulaire émaillée à décor géométrique", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0009_fibule_plaque_rectangulaire_emaillee_geometrique.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0009.jpg", "vignette": null, "nature": ["Fibules"], "dimensions": "3,6 x 1,3 cm", "poids": "", "dateMin": 100, "dateMax": 300, "datation": "Époque romaine, probablement IIe–IIIe siècle", "epoque": ["Antiquité"], "culture": ["Romaine"], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": ["Émail"], "technique": ["Émaillé"], "decor": ["Géométrique"], "fonctionUsage": ["Vie quotidienne"], "particularites": "Petite fibule-plaque allongée, centrée sur une plaque rectangulaire bordée de moulures. La face conserve une succession de petits motifs losangiques ou cruciformes et des traces d’émail clair. Le profil est nettement arqué. Le système d’attache au revers est incomplet.", "usageTexte": "Cette fibule permettait de maintenir un vêtement. Sa plaque émaillée à décor géométrique restait visible comme élément de parure.", "texteAnalyse": "La plaque rectangulaire décorée, le profil arqué et les éléments conservés du système d’attache permettent d’identifier une fibule romaine émaillée.\n\nLa plaque émaillée compartimentée et la construction du système de fixation conduisent à une datation de travail de 100 à 300 apr. J.-C., probablement aux IIe-IIIe siècles.\n\nLe décor de petits motifs losangiques ou cruciformes individualise l’exemplaire, mais aucun sous-type plus précis n’est retenu sans parallèle suffisamment proche."}, {"id": "OBJ-0010", "designation": "Fibule à plaque losangique émaillée", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0010_fibule_plaque_losangique_emaillee.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0010.jpg", "vignette": null, "nature": ["Fibules"], "dimensions": "3,4 x 1,5 cm", "poids": "", "dateMin": 100, "dateMax": 300, "datation": "Époque romaine, probablement IIe–IIIe siècle", "epoque": ["Antiquité"], "culture": ["Romaine"], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": ["Émail"], "technique": ["Émaillé"], "decor": ["Géométrique"], "fonctionUsage": ["Vie quotidienne"], "particularites": "Petite fibule organisée autour d’une plaque centrale losangique divisée en quatre compartiments, avec des traces d’émail verdâtre et rouge. Une extrémité présente un décor annulaire et les bordures de petites moulures. L’ardillon est conservé au revers.", "usageTexte": "L’ardillon traversait le tissu puis se bloquait dans le porte-ardillon afin de maintenir le vêtement. La plaque losangique émaillée formait la partie décorative visible.", "texteAnalyse": "La plaque centrale losangique compartimentée, l’émail et le système d’attache permettent d’identifier avec une bonne confiance une fibule romaine émaillée.\n\nLa construction et le décor conduisent à retenir une datation de travail de 100 à 300 apr. J.-C., avec une probabilité plus forte pour les IIe-IIIe siècles.\n\nL’ardillon est conservé, ce qui rend le fonctionnement de la fibule particulièrement lisible. La désignation à plaque losangique est retenue sans chercher à préciser davantage le sous-type."}, {"id": "OBJ-0011", "designation": "Fibule arquée à décor d’ocelles", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0011_ Fibule ansée symétrique à bras égaux.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0011.jpg", "vignette": null, "nature": ["Fibules"], "dimensions": "5 x 1,7 cm", "poids": "", "dateMin": 600, "dateMax": 900, "datation": "Haut Moyen Âge, attribution culturelle à préciser", "epoque": ["Haut Moyen Âge"], "culture": [], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Incisé", "Poinçonné"], "decor": ["Géométrique"], "fonctionUsage": ["Vie quotidienne"], "particularites": "Fibule allongée et fortement arquée. La face porte plusieurs excroissances ou disques ornés d’ocelles, formés de petits cercles concentriques avec point central. Le corps est étroit et longitudinal et le profil présente une courbure très marquée. Le revers conserve des éléments du dispositif d’attache.", "usageTexte": "Cette fibule servait à fermer ou maintenir une pièce de vêtement. La forte courbure de l’arc ménageait l’espace nécessaire au passage du tissu.", "texteAnalyse": "L’identification comme fibule est bien établie par la morphologie et les vestiges du système d’attache.\n\nLa forme générale et le décor d’ocelles orientent vers le haut Moyen Âge. Une fourchette de travail de 600 à 900 est retenue, mais reste prudente.\n\nLe décor d’ocelles est largement répandu et ne permet pas, à lui seul, de déterminer une culture précise. Aucune attribution mérovingienne, carolingienne ou germanique n’est donc retenue actuellement."}, {"id": "OBJ-0012", "designation": "Fibule-plaque romaine à extrémités symétriques", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0012_Fibule-plaque romaine à extrémités symétriques.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0012.jpg", "vignette": null, "nature": ["Fibules"], "dimensions": "3,2 x 1,9 cm", "poids": "", "dateMin": 100, "dateMax": 300, "datation": "Époque romaine, probablement IIe–IIIe siècle", "epoque": ["Antiquité"], "culture": ["Romaine"], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Moulé"], "decor": ["Zoomorphe"], "fonctionUsage": ["Vie quotidienne"], "particularites": "Petite fibule zoomorphe dont la silhouette évoque une tortue stylisée. Une extrémité forme une tête avec museau, tandis que le corps central massif, encadré de fortes moulures transversales, peut être interprété comme une carapace. Le revers est épais et arqué et conserve des vestiges du système de fixation.", "usageTexte": "Cette fibule se portait sur le vêtement comme système de fermeture ou de maintien. Sa forme animale lui donnait également une fonction décorative.", "texteAnalyse": "La lecture zoomorphe en tortue est assez convaincante : l’extrémité évoquant une tête et le corps massif à moulures transversales forment une silhouette cohérente. Cette interprétation reste toutefois prudente en l’absence d’un parallèle typologique strictement identique.\n\nLa construction de la fibule et son système d’attache sont compatibles avec une production romaine. La fourchette 100 à 300 apr. J.-C. est retenue, avec une probabilité plus forte pour les IIe-IIIe siècles.\n\nLe revers conserve des vestiges du dispositif de fixation."}, {"id": "OBJ-0013", "designation": "Deux ardillons de boucles de ceinture à base scutiforme", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0013_deux_ardillons_boucles_merovingiens.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0013.jpg", "vignette": null, "nature": ["Parures vestimentaires"], "dimensions": "Petit : 3,2 x 1,8 cm ; grand : 3,7 x 1,8 cm", "poids": "", "dateMin": 500, "dateMax": 700, "datation": "Haut Moyen Âge, culture probablement mérovingienne", "epoque": ["Haut Moyen Âge"], "culture": [], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Poinçonné"], "decor": ["Géométrique"], "fonctionUsage": ["Vie quotidienne"], "particularites": "Deux pièces présentant chacune une longue pointe courbe et une base élargie en forme d’écu. Le petit exemplaire porte des impressions triangulaires ou cunéiformes disposées en rangées obliques et en petits chevrons. Les reliefs du revers correspondent à la zone d’articulation sur l’axe de la boucle.", "usageTexte": "Chaque ardillon était articulé sur l’axe d’une boucle de ceinture. Sa pointe venait s’engager dans un trou de la courroie pour fermer et régler la ceinture.", "texteAnalyse": "La morphologie permet une identification assez sûre comme ardillons de boucles de ceinture, notamment grâce à la longue pointe courbe et à la base élargie scutiforme.\n\nLa forme oriente vers le haut Moyen Âge. Une datation de travail de 500 à 700 est retenue. Une attribution mérovingienne est probable, mais elle n’est pas suffisamment assurée pour être imposée comme civilisation dans les critères structurés.\n\nLe petit exemplaire conserve un décor poinçonné géométrique particulièrement lisible, composé de petites impressions triangulaires ou cunéiformes disposées en rangées et en chevrons."}, {"id": "OBJ-0014", "designation": "Fibule aviforme mérovingienne", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0014_fibule_aviforme_merovingienne.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0014.jpg", "vignette": null, "nature": ["Fibules"], "dimensions": "4 x 2 cm", "poids": "", "dateMin": 500, "dateMax": 600, "datation": "VIe siècle", "epoque": ["Haut Moyen Âge"], "culture": ["Barbare", "Mérovingienne"], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Incisé"], "decor": ["Zoomorphe"], "fonctionUsage": ["Vie quotidienne"], "particularites": "Fibule en forme d’oiseau à silhouette très lisible : tête relevée, bec fortement recourbé, œil circulaire marqué et corps compact. L’aile est soulignée par un décor incisé ou moulé. Le revers conserve le dispositif de broche, avec ardillon et éléments de fixation.", "usageTexte": "Cette petite fibule servait à fermer ou maintenir un vêtement. Sa forme d’oiseau en faisait également un élément de parure visible.", "texteAnalyse": "La morphologie aviforme, le bec fortement recourbé, l’œil circulaire et le traitement stylisé de l’aile correspondent aux fibules-oiseaux du monde franc et mérovingien.\n\nUne datation au VIe siècle, soit environ 500 à 600, est retenue. L’identification comme fibule aviforme mérovingienne est considérée comme solide.\n\nLe revers conserve suffisamment du dispositif de broche, notamment l’ardillon et les éléments de fixation, pour rendre le fonctionnement de l’objet clairement lisible."}, {"id": "OBJ-0015", "designation": "Deux garnitures de ceinture norico-pannoniennes à têtes de canard stylisées", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0015_garnitures_ceinture_canards_norico-pannoniennes.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0015.jpg", "vignette": null, "nature": ["Parures vestimentaires"], "dimensions": "Petit : 3,7 x 2,1 cm ; grand : 4 x 2 cm", "poids": "", "dateMin": 40, "dateMax": 150, "datation": "Époque romaine, Ier–milieu du IIe siècle apr. J.-C.", "epoque": ["Antiquité"], "culture": ["Romaine"], "aireGeographique": ["Norique", "Pannonie"], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Moulé"], "decor": ["Zoomorphe"], "fonctionUsage": ["Vie quotidienne"], "particularites": "Deux petites pièces de dimensions très proches figurant chacune une tête de canard stylisée. La tête, le bec et le profil d’oiseau sont nettement lisibles. Chaque pièce présente une protubérance verticale près de la tête ainsi que des éléments de construction au revers, probablement liés à un système de liaison ou d’articulation.", "usageTexte": "Ces éléments appartenaient probablement à une garniture de ceinture articulée. Ils pouvaient assurer la liaison entre plusieurs pièces métalliques tout en participant au décor de la ceinture.", "texteAnalyse": "La morphologie zoomorphe et les éléments de construction rapprochent ces deux pièces d’accessoires de ceinture romains de tradition norico-pannonienne à têtes de canard stylisées.\n\nLa protubérance visible près de la tête paraît davantage correspondre à un système de liaison ou d’articulation qu’à une simple patte destinée à traverser le cuir.\n\nLes meilleurs parallèles disponibles conduisent à retenir une datation de travail d’environ 40 à 150 apr. J.-C. L’attribution norico-pannonienne est probable, sans chercher à imposer un sous-type plus précis."}, {"id": "OBJ-0016", "designation": "Paire de garnitures de courroie à têtes canines", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0016_Paire de garnitures de courroie à têtes canines.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0016.jpg", "vignette": null, "nature": ["Parures vestimentaires"], "dimensions": "4 et 4,2 x 1,5 cm", "poids": "", "dateMin": 600, "dateMax": 900, "datation": "Haut Moyen Âge", "epoque": ["Haut Moyen Âge"], "culture": [], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Incisé"], "decor": ["Zoomorphe"], "fonctionUsage": ["Vie quotidienne"], "particularites": "Deux pièces presque identiques, longues d’environ 4 à 4,2 cm. Chaque élément possède un corps allongé légèrement courbe et une extrémité élargie figurant nettement une tête canine. Des lignes incisées soulignent la tête et le corps de l’animal.", "usageTexte": "Ces pièces étaient probablement fixées à l’extrémité d’une courroie ou d’une ceinture. Elles protégeaient et rigidifiaient la terminaison de la lanière tout en la décorant.", "texteAnalyse": "La morphologie générale et les dimensions sont compatibles avec des garnitures terminales de courroie. Les extrémités zoomorphes figurent clairement des têtes canines.\n\nDes garnitures de courroie zoomorphes comparables sont attestées au haut Moyen Âge. Une fourchette de travail de 600 à 900 est retenue.\n\nL’attribution culturelle reste ouverte ; aucun groupe particulier n’est imposé dans les critères structurés."}, {"id": "OBJ-0017", "designation": "Petite applique aviforme franque à tenon de fixation", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0017_applique_aviforme_franque.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0017.jpg", "vignette": null, "nature": ["Parures vestimentaires"], "dimensions": "1,9 x 0,9 cm environ, hors tenon", "poids": "", "dateMin": 500, "dateMax": 600, "datation": "VIe siècle probable", "epoque": ["Haut Moyen Âge"], "culture": ["Barbare", "Mérovingienne"], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Doré"], "decor": ["Zoomorphe"], "fonctionUsage": ["Vie quotidienne"], "particularites": "Petite applique figurant un oiseau au corps très allongé et à la tête relevée. Le revers présente un tenon rectangulaire massif, incompatible avec le système d’attache habituel d’une fibule. Un petit reste métallique doré visible sur la surface est compatible avec un vestige de dorure ancienne.", "usageTexte": "Cette petite garniture était fixée sur un support organique aujourd’hui disparu, probablement une courroie, une bourse ou un élément d’habillement, qu’elle servait à décorer.", "texteAnalyse": "La silhouette aviforme est claire, mais le système de fixation est déterminant : le tenon rectangulaire massif du revers conduit à identifier l’objet comme une applique ou une garniture décorative plutôt que comme une fibule.\n\nUn petit éclat doré subsiste sur la surface et peut correspondre à un vestige de dorure ancienne. L’état de conservation ne permet pas de préciser davantage la technique ni l’étendue initiale de cette dorure.\n\nUne datation de 500 à 600, avec une préférence pour le VIe siècle, est retenue. Des appliques aviformes comparables sont connues dans le monde franc. Le support précis de cet exemplaire reste toutefois indéterminé."}, {"id": "OBJ-0018", "designation": "Fibule aviforme franque à ailes déployées", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0018_fibule_aviforme_franque.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0018.jpg", "vignette": null, "nature": ["Fibules"], "dimensions": "3,3 x 1,7 cm", "poids": "", "dateMin": 400, "dateMax": 600, "datation": "Ve–VIe siècles, probabilité plus forte pour le VIe siècle", "epoque": ["Haut Moyen Âge"], "culture": ["Barbare", "Mérovingienne"], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Moulé"], "decor": ["Zoomorphe"], "fonctionUsage": ["Vie quotidienne"], "particularites": "Petite fibule représentant un oiseau aux ailes largement déployées. Le corps est allongé et la queue bifide. Le revers conserve un dispositif de broche bien lisible avec élément de charnière et ardillon.", "usageTexte": "Cette fibule servait à fixer ou maintenir le vêtement. La silhouette d’oiseau aux ailes ouvertes constituait également un motif de parure très visible.", "texteAnalyse": "La représentation aviforme est clairement lisible : corps allongé, ailes largement déployées et queue bifide. Le dispositif de broche largement conservé au revers confirme sans ambiguïté la fonction de fibule.\n\nLes petites fibules aviformes sont bien attestées dans le monde franc des Ve-VIe siècles. Une fourchette de 400 à 600 est retenue, avec une probabilité plus forte pour le VIe siècle.\n\nLa représentation est suffisamment claire pour être décrite directement comme un oiseau aux ailes déployées, sans qu’il soit nécessaire de préciser une espèce."}, {"id": "OBJ-0019", "designation": "Fibule aviforme, oiseau terrestre, perdrix probable", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0019_fibule_aviforme_oiseau_terrestre_perdrix_probable.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0019.jpg", "vignette": null, "nature": ["Fibules"], "dimensions": "2,9 x 1,2 cm", "poids": "", "dateMin": 400, "dateMax": 600, "datation": "Ve–VIe siècles", "epoque": ["Haut Moyen Âge"], "culture": ["Barbare", "Mérovingienne"], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Doré"], "decor": ["Zoomorphe"], "fonctionUsage": ["Vie quotidienne"], "particularites": "Petite fibule aviforme en alliage cuivreux, au corps allongé et fuselé et à la queue pointue. Un petit éclat métallique doré subsiste sur la surface, compatible avec une dorure ancienne presque entièrement disparue. Le revers conserve les vestiges du système d’attache. La lecture actuelle privilégie un oiseau terrestre, probablement une perdrix.", "usageTexte": "Cette fibule servait à fermer ou maintenir un vêtement. Sa forme d’oiseau et sa probable dorure en faisaient également un élément de parure particulièrement visible.", "texteAnalyse": "L’identification comme petite fibule aviforme est bien établie par la silhouette et les vestiges du système d’attache conservés au revers.\n\nLa morphologie et les dimensions sont compatibles avec les petites fibules aviformes du monde franc et mérovingien des Ve-VIe siècles. Une fourchette de travail de 400 à 600 est conservée.\n\nUn petit vestige métallique doré rend probable l’existence d’une dorure ancienne. La lecture figurative actuelle privilégie un oiseau terrestre, avec une identification comme perdrix probable ; cette précision zoologique demeure toutefois une hypothèse."}, {"id": "OBJ-0020", "designation": "Fibule zoomorphe, tête de canard très probable", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0020_Fibule_zoomorphe_tete_de_canard_tres_probable.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0020.jpg", "vignette": null, "nature": ["Fibules"], "dimensions": "3,9 x 1 cm", "poids": "", "dateMin": null, "dateMax": null, "datation": "À déterminer", "epoque": [], "culture": [], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Moulé"], "decor": ["Zoomorphe"], "fonctionUsage": ["Vie quotidienne"], "particularites": "Petite fibule zoomorphe au corps allongé et bombé. Dans le sens de lecture retenu, une extrémité forme un bec large et aplati, suivi d’un bombement correspondant à la tête puis d’un rétrécissement évoquant le cou. Le revers conserve les éléments du système d’attache.", "usageTexte": "Cette fibule se portait sur un vêtement comme système de fixation et comme élément de parure. Sa tête animale constituait le principal motif décoratif.", "texteAnalyse": "La lecture antérieure comme mammifère aquatique ou castor est abandonnée. La réorientation de l’objet fait apparaître une morphologie aviforme beaucoup plus cohérente : bec large et aplati, tête arrondie et départ de cou. L’identification comme tête de canard est donc retenue avec une confiance élevée.\n\nCette nouvelle lecture figurative ne suffit cependant pas à déterminer la période ou la culture de l’objet. La datation, l’époque et l’attribution culturelle restent volontairement ouvertes.\n\nL’identification comme fibule est étayée par les éléments du système d’attache conservés au revers."}, {"id": "OBJ-0021", "designation": "Pendant de harnais en forme de croissant à décor d’ocelles", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0021_pendant_harnais_croissant_ocelles.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0021.jpg", "vignette": null, "nature": ["Parures vestimentaires"], "dimensions": "4,2 x 3,4 cm", "poids": "", "dateMin": 50, "dateMax": 250, "datation": "Époque romaine impériale, Ier–IIIe siècle", "epoque": ["Antiquité"], "culture": ["Romaine"], "aireGeographique": ["Empire romain"], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Poinçonné"], "decor": ["Géométrique"], "fonctionUsage": ["Vie quotidienne"], "particularites": "Grand pendentif en forme de croissant ou lunule, couvert de nombreux petits cercles pointés ou ocelles. Une bélière tubulaire très visible occupe la partie supérieure. Les deux extrémités inférieures sont allongées ; l’une conserve un petit ajour. Le revers est plat et présente plusieurs petits orifices.", "usageTexte": "Ce pendant faisait partie du harnachement d’un cheval. Suspendu à une courroie ou à un élément métallique, il se déplaçait avec les mouvements de l’animal et constituait principalement un ornement.", "texteAnalyse": "La forme générale en croissant et surtout la présence d’une bélière supérieure permettent d’identifier l’objet comme un pendant de harnais.\n\nLa face est ornée d’un semis d’ocelles ou cercles pointés, probablement obtenus par poinçonnage. La forme de lunule est caractéristique de l’objet.\n\nLes pendants de harnais en forme de croissant sont bien attestés à l’époque romaine impériale. Une fourchette de travail de 50 à 250 apr. J.-C. est retenue."}, {"id": "OBJ-0022", "designation": "Antoninien de Gallien, type LIBERALITAS AVGG", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0022_antoninien_Gallien_Liberalitas_AVGG.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0022.jpg", "vignette": null, "nature": ["Monnaies"], "dimensions": "Diamètre 22 mm ; épaisseur environ 1,5 mm", "poids": "", "dateMin": 256, "dateMax": 256, "datation": "Vers 256", "epoque": ["Antiquité"], "culture": ["Romaine"], "aireGeographique": ["Empire romain"], "materiauxMetalliques": ["Billon"], "materiauxNonMetalliques": [], "technique": ["Frappé"], "decor": ["Anthropomorphe", "Inscription / épigraphique"], "fonctionUsage": ["Vie quotidienne"], "particularites": "Antoninien au flan irrégulier. À l’avers, Gallien est représenté radié et cuirassé à droite ; la légende IMP C P LIC GALLIENVS P F AVG est largement lisible. Le revers porte la légende LIBERALITAS AVGG et semble représenter Valérien Ier et Gallien assis, avec le jeune Valérien II entre eux.", "usageTexte": "L’antoninien était une monnaie de circulation de l’Empire romain. Il servait aux échanges tout en diffusant le portrait impérial et un message politique ; ici, la générosité des empereurs et probablement la continuité de la dynastie.", "texteAnalyse": "Le portrait radié et cuirassé ainsi que la légende de l’avers permettent d’identifier Gallien et la dénomination comme antoninien.\n\nLa légende LIBERALITAS AVGG renvoie à la générosité des deux Augustes. Les reliefs du revers semblent représenter Valérien Ier et Gallien assis sur des sièges curules, avec Valérien II entre eux, formant une représentation dynastique sur trois générations. L’usure impose toutefois de conserver une réserve sur cette variante exacte.\n\nLa comparaison avec le type MIR 68q / RIC V.1 150 oriente vers l’atelier de Rome et une émission vers 256. La monnaie est classée en billon ; sa teneur exacte en argent n’est pas connue."}, {"id": "OBJ-0023", "designation": "Denier d’Antonin le Pieux, type Salus", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0023_denier_Antonin_le_Pieux_Salus.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0023.jpg", "vignette": null, "nature": ["Monnaies"], "dimensions": "Diamètre 18 mm ; épaisseur env. 1 mm", "poids": "", "dateMin": 156, "dateMax": 157, "datation": "156–157", "epoque": ["Antiquité"], "culture": ["Romaine"], "aireGeographique": ["Empire romain"], "materiauxMetalliques": ["Argent"], "materiauxNonMetalliques": [], "technique": ["Frappé"], "decor": ["Anthropomorphe", "Zoomorphe", "Inscription / épigraphique"], "fonctionUsage": ["Vie quotidienne"], "particularites": "Denier au flan légèrement irrégulier. À l’avers, tête laurée d’Antonin le Pieux tournée à droite, avec la légende ANTONINVS AVG PIVS P P IMP II. Au revers, Salus est assise à gauche et tend une patère vers un serpent enroulé autour d’un autel. Quelques dépôts et traces verdâtres sont visibles.", "usageTexte": "Le denier était une monnaie d’argent de circulation. Le portrait et les légendes affirmaient l’autorité impériale ; le revers à Salus associait l’émission à la santé, à la sauvegarde et à la prospérité de l’empereur et de l’État.", "texteAnalyse": "Le portrait et la titulature de l’avers correspondent aux émissions tardives du règne d’Antonin le Pieux.\n\nAu revers, Salus est assise à gauche et nourrit à l’aide d’une patère un serpent enroulé autour d’un autel. La légende TR POT XX COS IIII et cette composition correspondent au denier RIC III 264.\n\nCe type est attribué à l’atelier de Rome et daté de 156-157 apr. J.-C. L’identification typologique est forte. Le poids n’a pas été mesuré."}, {"id": "OBJ-0024", "designation": "As républicain romain à Janus et proue (probable)", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0024_bronze_republicain_Janus_proue.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0024.jpg", "vignette": null, "nature": ["Monnaies"], "dimensions": "Diamètre 19 mm ; épaisseur env. 2 mm", "poids": "", "dateMin": -211, "dateMax": -80, "datation": "République romaine, fin du IIIe-début du Ier siècle av. J.-C.", "epoque": ["Antiquité"], "culture": ["Romaine"], "aireGeographique": [], "materiauxMetalliques": ["Bronze / alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Frappé"], "decor": ["Anthropomorphe", "Naval"], "fonctionUsage": ["Vie quotidienne", "Monnaie"], "particularites": "Petit bronze au flan irrégulier. Une face montre une tête double ou janiforme compatible avec Janus. L’autre, beaucoup plus usée, présente un motif interprétable comme une proue de navire. Le diamètre de 19 mm est relativement faible pour de nombreux asses républicains.", "usageTexte": "Cette monnaie de bronze servait aux échanges quotidiens. Le couple iconographique Janus à l’avers et proue de navire au revers est caractéristique du monnayage républicain romain.", "texteAnalyse": "La tête janiforme est compatible avec Janus, tandis que l’organisation générale de l’autre face évoque une proue de navire. Cette association correspond à un type classique des bronzes de la République romaine.\n\nUne datation de travail comprise entre 211 et 80 av. J.-C. est retenue. L’usure ne permet pas de lire avec certitude une marque de valeur, un nom de monétaire ou la légende ROMA.\n\nL’identification comme as reste probable plutôt que certaine : le diamètre de 19 mm est inférieur à celui de nombreux asses républicains de référence et le poids n’a pas été mesuré. Une pesée permettrait de mieux préciser la dénomination."}, {"id": "OBJ-0025", "designation": "Bronze d’Antiochos Ier de Commagène, aigle", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0025_bronze_Antiochos_I_Commagene_aigle.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0025.jpg", "vignette": null, "nature": ["Monnaies"], "dimensions": "Diamètre 16 mm ; épaisseur 1 mm", "poids": "", "dateMin": -69, "dateMax": -34, "datation": "-69 à -34 ; règne d’Antiochos Ier", "epoque": ["Antiquité"], "culture": ["Commagène / hellénistique"], "aireGeographique": ["Royaume de Commagène"], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Frappé"], "decor": ["Anthropomorphe", "Zoomorphe", "Inscription / épigraphique"], "fonctionUsage": ["Vie quotidienne"], "particularites": "Petit bronze de 16 mm présentant à l’avers la tête d’Antiochos Ier tournée à droite, coiffée d’une haute tiare royale. Le revers montre un aigle debout à droite et porte la légende grecque ΒΑΣΙΛΕΩΣ ΑΝΤΙΟΧΟΥ, « du roi Antiochos ». La surface est usée mais les principaux éléments du type restent lisibles.", "usageTexte": "Cette monnaie circulait dans le royaume de Commagène. Elle servait aux échanges tout en affirmant l’autorité royale par le portrait du souverain, sa titulature grecque et l’image de l’aigle.", "texteAnalyse": "Le portrait royal à la haute tiare et le revers à l’aigle permettent une attribution très probable à Antiochos Ier de Commagène.\n\nLa légende grecque ΒΑΣΙΛΕΩΣ ΑΝΤΙΟΧΟΥ signifie « du roi Antiochos ». L’ensemble correspond très probablement au type RPC I 3847 / Kovacs 226, dont le diamètre de référence est compatible avec les 16 mm mesurés sur cet exemplaire.\n\nAntiochos Ier régna sur la Commagène de 69 à 34 av. J.-C. La monnaie est donc datée de cette période. Le poids n’a pas été mesuré."}, {"id": "OBJ-0026", "designation": "Bronze d’Hadrien au cerf, Éphèse", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0026_bronze_Hadrien_cerf_Ephese.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0026.jpg", "vignette": null, "nature": ["Monnaies"], "dimensions": "Diamètre 22 mm ; épaisseur 1 mm", "poids": "", "dateMin": 117, "dateMax": 138, "datation": "117–138 ; règne d’Hadrien", "epoque": ["Antiquité"], "culture": ["Romaine"], "aireGeographique": ["Éphèse / province romaine d’Asie"], "materiauxMetalliques": ["Alliage cuivreux / bronze"], "materiauxNonMetalliques": [], "technique": ["Frappé"], "decor": ["Anthropomorphe", "Zoomorphe"], "fonctionUsage": ["Vie quotidienne"], "particularites": "Bronze provincial romain très usé. L’avers montre une tête masculine laurée tournée à droite, compatible avec Hadrien. Au revers, le relief central conserve la silhouette d’un quadrupède interprété comme un cerf.", "usageTexte": "Cette monnaie servait aux échanges dans le cadre du monnayage provincial romain. Le portrait impérial affirmait l’autorité de Rome, tandis que le cerf renvoyait probablement à Artémis, divinité majeure d’Éphèse.", "texteAnalyse": "Le portrait de l’avers, malgré son usure, est compatible avec Hadrien. Au revers, la lecture en cerf est la plus vraisemblable parmi les reliefs encore visibles.\n\nÉphèse a émis sous Hadrien des bronzes montrant un cerf, notamment les types RPC III 2069 et 2070. L’usure de cet exemplaire ne permet pas de déterminer sûrement l’orientation de l’animal ni de choisir entre ces variantes.\n\nL’attribution de travail retenue est donc un bronze provincial romain d’Hadrien frappé à Éphèse entre 117 et 138. Le diamètre de 22 mm reste compatible avec cette famille d’émissions."}, {"id": "OBJ-0027", "designation": "Fibule romaine à charnière, type Aucissa probable", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0027_fibule_romaine_aucissa_probable.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0027.jpg", "vignette": null, "nature": ["Fibules"], "dimensions": "58 x 28 mm", "poids": "", "dateMin": -20, "dateMax": 80, "datation": "Fin du Ier siècle av. J.-C. – Ier siècle apr. J.-C.", "epoque": ["Antiquité"], "culture": ["Romaine"], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Charnière", "Arc semi-circulaire"], "decor": [], "fonctionUsage": ["Vie quotidienne"], "particularites": "Fibule en alliage cuivreux à arc fortement cintré, presque semi-circulaire. La tête conserve une charnière et l’ardillon articulé. Le pied se prolonge par un porte-ardillon plein et développé. La pièce paraît globalement complète.", "usageTexte": "Cette fibule servait à fixer et maintenir une pièce de vêtement. L’ardillon articulé traversait le tissu puis venait se loger dans le porte-ardillon.", "texteAnalyse": "La combinaison d’une charnière, d’un arc haut presque semi-circulaire et d’un porte-ardillon plein rapproche nettement cette fibule de la famille Aucissa.\n\nL’absence d’inscription ou de décor caractéristique impose toutefois de conserver une attribution prudente : type Aucissa ou forme dérivée, sans sous-type précis.\n\nLes fibules Aucissa apparaissent à la fin de la République romaine et sont particulièrement répandues au Ier siècle apr. J.-C. Une fourchette de travail de -20 à 80 est retenue pour cet exemplaire."}, {"id": "OBJ-0028", "designation": "Fragment probable de fibule à lunettes en bronze", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0028_fragment_probable_fibule_a_lunettes_bronze.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0028.jpg", "vignette": null, "nature": ["Fibules"], "dimensions": "Diamètre de la spirale 28 mm ; diamètre de la tige env. 2 mm", "poids": "", "dateMin": -900, "dateMax": -650, "datation": "Premier âge du Fer, datation de travail", "epoque": ["Protohistoire"], "culture": ["Protohistoire européenne"], "aireGeographique": ["tradition hallstattienne / italique à préciser"], "materiauxMetalliques": ["Alliage cuivreux", "Bronze"], "materiauxNonMetalliques": [], "technique": ["tige enroulée ; mise en forme probable par martelage et pliage"], "decor": ["Géométrique", "Spiralé"], "fonctionUsage": ["Parure vestimentaire", "Élément de fibule probable"], "particularites": "Élément en alliage cuivreux constitué d’une tige d’environ 2 mm enroulée régulièrement en spirale plane de 28 mm. Une seule spirale est conservée ; la seconde et le système d’attache manquent.", "usageTexte": "S’il s’agit bien d’un fragment de fibule à lunettes, cette spirale appartenait à une grande parure métallique destinée à fixer ou orner le vêtement.", "texteAnalyse": "La forme régulière de la spirale et ses dimensions sont très compatibles avec l’une des deux spirales constituant une fibule à lunettes. L’identification reste probable puisque la seconde spirale et le dispositif d’attache ne sont pas conservés.\n\nL’hypothèse d’une simple réserve de matière ou d’un semi-produit a été envisagée. La régularité de l’enroulement et les dimensions rendent toutefois une fonction d’ornement plus vraisemblable.\n\nLes fibules à lunettes sont bien attestées au premier âge du Fer. Une fourchette volontairement large de -900 à -650 est retenue tant que l’origine géographique précise de l’objet reste inconnue."}, {"id": "OBJ-0029", "designation": "Fibule romaine à charnière, type Hod Hill probable", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0029_fibule_romaine_type_Hod_Hill_probable.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0029.jpg", "vignette": null, "nature": ["Fibules"], "dimensions": "73 x 36 mm", "poids": "", "dateMin": 40, "dateMax": 70, "datation": "Milieu du Ier siècle apr. J.-C.", "epoque": ["Antiquité"], "culture": ["Romaine"], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux", "Bronze"], "materiauxNonMetalliques": [], "technique": ["Charnière tubulaire", "Moulé"], "decor": ["Géométrique"], "fonctionUsage": ["Parure vestimentaire", "Fixation"], "particularites": "Fibule romaine longue et étroite, à arc légèrement cintré. La tête roulée en tube forme la charnière. Trois moulures transversales marquent la partie haute de l’arc et un discret décor longitudinal est visible sur le corps. Le pied et une partie du porte-ardillon sont conservés ; l’axe et l’ardillon manquent.", "usageTexte": "Cette fibule servait à fixer une pièce de vêtement. L’ardillon, aujourd’hui disparu, pivotait dans la charnière tubulaire puis venait se bloquer dans le porte-ardillon.", "texteAnalyse": "La charnière tubulaire, l’arc long et relativement étroit et les moulures transversales rapprochent nettement cet exemplaire des fibules romaines de la famille Hod Hill.\n\nCes fibules sont caractéristiques du milieu du Ier siècle apr. J.-C. Une fourchette de travail de 40 à 70 est retenue sans chercher à imposer un sous-type plus précis.\n\nL’identification comme fibule romaine à charnière du Ier siècle est solide. L’attribution à la famille Hod Hill reste probable, notamment parce que le système d’attache est incomplet."}, {"id": "OBJ-0030", "designation": "Follis byzantin de Théophile, Syracuse, probable", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0030_follis_byzantin_Theophile_Syracuse_probable.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0030.jpg", "vignette": null, "nature": ["Monnaies"], "dimensions": "Diamètre 20 mm ; épaisseur env. 3 mm", "poids": "", "dateMin": 829, "dateMax": 842, "datation": "Règne de Théophile, 829-842", "epoque": ["Moyen Âge"], "culture": ["Byzantine"], "aireGeographique": ["Syracuse", "Sicile"], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Frappé"], "decor": ["Grand M", "Croix", "XXX / NNN"], "fonctionUsage": ["Vie quotidienne", "Monnaie"], "particularites": "Petit bronze byzantin très usé et corrodé, frappé sur un flan irrégulier et épais. Le revers présente un grand M entouré de signes très altérés dont l’organisation est compatible avec des colonnes XXX et NNN et une croix au-dessus. L’avers est fortement usé et ne permet pas de lire sûrement le portrait ni la légende.", "usageTexte": "Le follis était une monnaie de bronze destinée à la circulation courante dans l’Empire byzantin. Ses motifs, signes et marques permettaient également d’identifier l’autorité et l’atelier émetteur.", "texteAnalyse": "L’identification générale comme bronze byzantin de type follis repose notamment sur le grand M très visible au revers et sur la disposition des signes périphériques.\n\nL’attribution initialement envisagée à Constans II a été abandonnée. L’organisation du revers, avec le grand M, la croix et les groupes de signes compatibles avec XXX et NNN, correspond mieux aux folles de Théophile frappés à Syracuse.\n\nL’attribution retenue est donc Théophile, atelier de Syracuse, probablement sous son règne entre 829 et 842. L’état très usé de l’avers justifie de conserver le qualificatif probable."}, {"id": "OBJ-0031", "designation": "Denier de Charlemagne, atelier de Dorestad, probable", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0031_denier_Charlemagne_Dorestad_probable.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0031.jpg", "vignette": null, "nature": ["Monnaies"], "dimensions": "Diamètre 17 mm ; épaisseur env. 0,5 mm", "poids": "", "dateMin": 781, "dateMax": 812, "datation": "Fin VIIIe - début IXe siècle, env. 781-812", "epoque": ["Moyen Âge"], "culture": ["Carolingienne"], "aireGeographique": ["Dorestad", "Frise", "Pays-Bas actuels"], "materiauxMetalliques": ["Argent"], "materiauxNonMetalliques": [], "technique": ["Frappé"], "decor": ["Croix", "Monogramme carolingien", "Inscription / épigraphique"], "fonctionUsage": ["Vie quotidienne", "Monnaie"], "particularites": "Petit denier sur flan mince, irrégulier et légèrement ondulé. La morphologie et les éléments lisibles correspondent très probablement à un denier carolingien de Charlemagne frappé à Dorestad.", "usageTexte": "Ce denier était une monnaie de circulation. Les légendes, la croix et le monogramme associaient la valeur monétaire à l’autorité de Charlemagne et à l’atelier émetteur.", "texteAnalyse": "L’identification typologique comme denier carolingien attribué à Charlemagne et à l’atelier de Dorestad est très probable. Les parallèles présentent notamment les légendes CARLVS REX FR et DORESTADO, associées à une croix et à un monogramme carolingien.\n\nLe flan de 17 mm est mince, irrégulier et légèrement ondulé, ce qui est compatible avec une monnaie frappée au marteau. Aucun joint de moulage évident n’a été relevé sur les photographies.\n\nUne fourchette de travail de 781 à 812 est conservée. Les types comparables de Dorestad sont notamment connus vers 793-812. L’authenticité matérielle ne peut toutefois pas être certifiée sur photographies seules."}, {"id": "OBJ-0032", "designation": "Denier melgorien, comté de Melgueil", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0032_denier_melgorien_comte_Melgueil.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0032.jpg", "vignette": null, "nature": ["Monnaies"], "dimensions": "Diamètre 16 mm ; épaisseur env. 0,5 mm", "poids": "", "dateMin": 1080, "dateMax": 1120, "datation": "Vers 1080-1120", "epoque": ["Moyen Âge"], "culture": ["Languedoc médiéval"], "aireGeographique": ["Melgueil", "Maguelone", "Languedoc"], "materiauxMetalliques": ["Billon"], "materiauxNonMetalliques": [], "technique": ["Frappé"], "decor": ["Croix", "Annelets", "Inscription / épigraphique"], "fonctionUsage": ["Vie quotidienne", "Monnaie"], "particularites": "Petit denier anonyme en billon, frappé sur un flan irrégulier. Le type associe une grande croix, quatre annelets et les légendes dégénérées RAMVNDS / NAIDONA. Le poids n’a pas été mesuré.", "usageTexte": "Ce denier appartenait au monnayage régional de Melgueil et circulait comme monnaie de paiement dans le Languedoc médiéval.", "texteAnalyse": "L’identification comme denier melgorien est très solide grâce à la combinaison caractéristique de la grande croix, des quatre annelets et des légendes dégénérées RAMVNDS / NAIDONA.\n\nLes exemplaires comparables sont classés parmi les deniers anonymes du comté de Melgueil des XIe-XIIe siècles. Une fourchette de travail d’environ 1080 à 1120 est retenue pour cet exemplaire.\n\nLa monnaie est en billon, alliage d’argent à faible titre, et a été frappée au marteau sur un flan irrégulier de 16 mm. Ce monnayage est directement lié à Melgueil puis, dans son histoire ultérieure, aux évêques de Maguelone."}, {"id": "OBJ-0033", "designation": "Paire de garnitures creuses de mobilier, époque romaine probable", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0033_paire_garnitures_mobilier_romaines_probables.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0033.jpg", "vignette": null, "nature": ["Garnitures", "Appliques de mobilier"], "dimensions": "Env. 50 x 40 mm ; éléments tronqués", "poids": "", "dateMin": 1, "dateMax": 400, "datation": "Époque romaine, Ier-IVe siècle apr. J.-C., probable", "epoque": ["Antiquité"], "culture": ["Romaine"], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Moulé", "Fixation par pattes / tige probable"], "decor": ["Forme globulaire", "Surface lisse"], "fonctionUsage": ["Mobilier", "Fixation / ornement"], "particularites": "Deux éléments creux et fragmentaires à corps bombé ou globulaire, col court et extrémité discoïde. Les grandes ouvertures visibles correspondent à des cassures. Des saillies internes régulières peuvent correspondre à des pattes ou ergots de fixation. L’extrémité centrale est pleine et ne présente pas de trou de suspension.", "usageTexte": "Ces éléments étaient probablement fixés sur un meuble, un coffret, une porte ou un autre support pour assurer à la fois une fonction de fixation et d’ornement.", "texteAnalyse": "L’absence d’anneau ou de perforation fonctionnelle rend peu probable une utilisation comme pendentif. La combinaison d’un corps creux, d’un col court et d’éléments de fixation oriente plutôt vers des appliques, boutons ou garnitures de mobilier.\n\nDes rapprochements existent avec les garnitures romaines dites « bell-shaped studs », utilisées notamment sur des meubles, coffrets, portes ou véhicules. Le module de ces deux exemplaires est toutefois relativement important et aucun sous-type précis n’est retenu.\n\nUne datation prudente du Ier au IVe siècle apr. J.-C. est conservée. La surface sombre pourrait résulter de corrosion, d’un enfouissement ou éventuellement d’une altération thermique ancienne, mais cette dernière hypothèse ne peut pas être démontrée."}, {"id": "OBJ-0034", "designation": "Bague à chaton gravé, époque romaine tardive probable", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0034_bague_chatton_grave_romaine_tardive_probable.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0034.jpg", "vignette": null, "nature": ["Bagues", "Bijoux"], "dimensions": "Anneau intérieur env. 20 mm ; chaton env. 12 mm", "poids": "", "dateMin": 200, "dateMax": 400, "datation": "IIIe-IVe siècle apr. J.-C., probable", "epoque": ["Antiquité"], "culture": ["Romaine"], "aireGeographique": ["Empire romain"], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Moulé", "Gravé / incisé"], "decor": ["Motif végétal stylisé", "Palmette probable", "Décor géométrique"], "fonctionUsage": ["Parure", "Usage sigillaire possible"], "particularites": "Bague massive à anneau épais et épaules fortement élargies et carénées. Le chaton plat, ovale à presque circulaire, est gravé d’un motif végétal stylisé évoquant une palmette, une branche ou une feuille nervurée. Les épaules portent des chevrons et des traits incisés.", "usageTexte": "Cette bague était avant tout un bijou de parure personnelle. Le chaton gravé pouvait aussi servir de signe identitaire et éventuellement de sceau, mais cet usage sigillaire n’est pas démontré.", "texteAnalyse": "Le profil caréné des épaules, l’anneau épais et le chaton plat gravé orientent vers les bagues de l’époque romaine tardive.\n\nLe décor du chaton est composé d’une nervure centrale et de traits obliques pouvant être lus comme une palmette, une branche ou une feuille stylisée. Les épaules présentent également un décor géométrique incisé.\n\nUne datation prudente aux IIIe-IVe siècles apr. J.-C. est retenue, avec une préférence typologique pour le IVe siècle. Une attribution médiévale paraît moins convaincante au regard de la morphologie générale."}, {"id": "OBJ-0035", "designation": "Bronze de Philippe II de Macédoine, Apollon / cavalier, probable", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0035_bronze_Philippe_II_Macedoine_Apollon_cavalier_probable.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0035.jpg", "vignette": null, "nature": ["Monnaies"], "dimensions": "Diamètre 16 mm ; épaisseur env. 1,5 mm", "poids": "", "dateMin": -359, "dateMax": -294, "datation": "359-294 av. J.-C., type de Philippe II, frappes posthumes comprises", "epoque": ["Antiquité"], "culture": ["Macédonienne", "Grecque"], "aireGeographique": ["Macédoine"], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Frappé"], "decor": ["Anthropomorphe", "Équestre", "Inscription / épigraphique"], "fonctionUsage": ["Vie quotidienne", "Monnaie"], "particularites": "Petit bronze fortement corrodé. Une face présente une tête humaine de profil compatible avec Apollon portant une taenia. L’autre montre assez nettement un jeune cavalier à cheval. La légende et les éventuels symboles de contrôle ne sont plus lisibles.", "usageTexte": "Cette monnaie de bronze servait aux échanges. Le portrait d’Apollon et le cavalier constituaient un type monétaire associé au pouvoir de Philippe II de Macédoine.", "texteAnalyse": "Malgré la corrosion, la tête de profil est compatible avec les représentations d’Apollon portant une taenia sur les bronzes de Philippe II. Le revers montrant un jeune cavalier est plus nettement lisible et constitue un motif caractéristique de ce monnayage.\n\nLe diamètre de 16 mm correspond bien aux unités de bronze connues pour ce type. La légende PHILIPPOU et les éventuels symboles de contrôle ne peuvent cependant pas être lus sur cet exemplaire.\n\nLes émissions du règne de Philippe II débutent en 359 av. J.-C. et certaines séries de même type ont continué après sa mort. Une fourchette prudente de -359 à -294 est donc retenue. L’attribution à Philippe II est probable mais non absolument certaine."}, {"id": "OBJ-0036", "designation": "Petit cuilleron de toilette ou cosmétique en alliage cuivreux, romain probable", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0036_cuilleron_toilette_cosmetique_romain_probable.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0036.jpg", "vignette": null, "nature": ["Objets de toilette"], "dimensions": "Cuilleron ovale 20 x 15 mm ; manche incomplet", "poids": "", "dateMin": 1, "dateMax": 400, "datation": "Époque romaine, Ier-IVe siècle apr. J.-C., probable", "epoque": ["Antiquité"], "culture": ["Romaine"], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Façonné"], "decor": [], "fonctionUsage": ["Vie quotidienne", "Toilette / cosmétique"], "particularites": "Petit instrument en alliage cuivreux comportant un cuilleron ovale et peu profond de 20 x 15 mm. Le manche est cassé ; un épaulement net à la jonction montre qu’il se prolongeait par une tige plus fine.", "usageTexte": "Ce petit instrument pouvait servir à prélever, doser ou appliquer des baumes, onguents, parfums ou préparations cosmétiques.", "texteAnalyse": "Le faible module du cuilleron et la morphologie du départ de manche orientent davantage vers un instrument de toilette ou de cosmétique que vers une cuillère destinée à l’alimentation.\n\nDe petits instruments à cuilleron sont connus dans le monde romain pour les soins corporels, les cosmétiques et diverses préparations. La fonction précise de cet exemplaire ne peut toutefois pas être déterminée.\n\nEn l’absence de contexte archéologique ou de parallèle typologique plus précis, une datation large du Ier au IVe siècle apr. J.-C. est retenue."}, {"id": "OBJ-0037", "designation": "Fibule discoïde ajourée à décor rayonnant, romaine", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0037_fibule_discoide_ajouree_decor_rayonnant_romaine.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0037.jpg", "vignette": null, "nature": ["Fibules"], "dimensions": "Diamètre 52 mm ; épaisseur env. 1,5 mm ; attache env. 13 mm", "poids": "", "dateMin": 50, "dateMax": 200, "datation": "Ier-IIe siècle apr. J.-C.", "epoque": ["Antiquité"], "culture": ["Romaine"], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Moulé", "Ajouré"], "decor": ["Géométrique", "Rayonnant", "Roue"], "fonctionUsage": ["Parure vestimentaire", "Fixation"], "particularites": "Grande fibule discoïde en alliage cuivreux, moulée et largement ajourée. Le décor s’organise autour d’un moyeu central d’où partent huit branches courbes rayonnantes. Le bord extérieur est rythmé par une série régulière de petites saillies. Le revers conserve le support de l’ardillon et le porte-ardillon opposé.", "usageTexte": "Cette grande fibule servait à fixer un vêtement. Son disque largement ajouré et son décor rayonnant lui donnaient également une forte fonction ornementale.", "texteAnalyse": "Le système d’attache conservé au revers permet d’identifier avec assurance l’objet comme une fibule.\n\nLa composition ajourée organisée autour d’un moyeu central appartient au groupe des fibules-disques romaines à décor de roue ou de rosette rayonnante.\n\nUne datation comprise entre 50 et 200 apr. J.-C., soit les Ier-IIe siècles, est retenue pour cet exemplaire."}, {"id": "OBJ-0038", "designation": "Applique circulaire émaillée à décor concentrique, romaine", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0038_applique_circulaire_emaillee_decor_concentrique_romaine.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0038.jpg", "vignette": null, "nature": ["Appliques / garnitures"], "dimensions": "Diamètre 29 mm ; épaisseur env. 1,5 mm ; tenon central au revers", "poids": "", "dateMin": 100, "dateMax": 250, "datation": "IIe-début du IIIe siècle apr. J.-C.", "epoque": ["Antiquité"], "culture": ["Romaine"], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": ["Émail"], "technique": ["Moulé", "Émail champlevé"], "decor": ["Géométrique", "Concentrique", "Polychrome"], "fonctionUsage": ["Garniture décorative", "Fixation"], "particularites": "Applique discoïde en alliage cuivreux à décor concentrique émaillé. La face est divisée en plusieurs registres circulaires séparés par des nervures métalliques ; des vestiges d’émail rouge-orangé et sombre subsistent dans les cellules. Le revers est plat et porte au centre un tenon de fixation.", "usageTexte": "Cette applique était fixée sur un support au moyen de son tenon central. Elle avait principalement une fonction décorative, probablement sur un élément de mobilier, d’équipement ou de harnachement.", "texteAnalyse": "Le tenon central du revers montre qu’il ne s’agit pas d’une fibule mais d’une applique ou d’un clou décoratif destiné à être fixé sur un support.\n\nLe décor polychrome est réalisé en émail champlevé : les cavités aménagées dans la plaque recevaient les différentes couleurs d’émail, séparées par des nervures métalliques.\n\nL’organisation concentrique et le décor émaillé s’inscrivent dans le répertoire des garnitures romaines des IIe et début du IIIe siècles. Une datation de 100 à 250 apr. J.-C. est retenue."}, {"id": "OBJ-0039", "designation": "Fibule discoïde ajourée à motif de tourbillon à six branches, romaine", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0039_fibule_discoide_ajouree_tourbillon_six_branches_romaine.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0039.jpg", "vignette": null, "nature": ["Fibules"], "dimensions": "Diamètre 29 mm ; épaisseur env. 3 mm", "poids": "", "dateMin": 100, "dateMax": 200, "datation": "IIe siècle apr. J.-C.", "epoque": ["Antiquité"], "culture": ["Romaine"], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Moulé", "Ajouré"], "decor": ["Géométrique", "Curviligne", "Tourbillon à six branches", "Romano-celtique"], "fonctionUsage": ["Parure vestimentaire", "Fixation"], "particularites": "Fibule discoïde en alliage cuivreux, moulée et largement ajourée. Le décor s’organise autour d’un centre plein d’où partent six branches courbes disposées en mouvement tournant. Leurs extrémités élargies évoquent des motifs de trompette. Le revers conserve l’articulation de l’ardillon et le porte-ardillon opposé ; l’ardillon est perdu.", "usageTexte": "Cette fibule servait à fixer un vêtement. Son décor ajouré en mouvement tournant en faisait également un élément de parure particulièrement visible.", "texteAnalyse": "Les vestiges du système d’attache au revers permettent d’identifier l’objet comme une fibule malgré la disparition de l’ardillon.\n\nLa forme appartient au groupe des fibules-plaques ajourées romaines. Le motif curviligne à six branches et les terminaisons évoquant des trompettes s’inscrivent dans le vocabulaire décoratif romano-celtique des provinces occidentales de l’Empire.\n\nUne datation au IIe siècle apr. J.-C., soit environ 100 à 200, est retenue."}, {"id": "OBJ-0040", "designation": "Terret de harnais à fixation intégrée, époque romaine probable", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0040_terrets_harnais_comparaison_OBJ-0041.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0040.jpg", "vignette": null, "nature": ["Harnachement"], "dimensions": "58 x 42 mm ; épaisseur env. 3 mm", "poids": "", "dateMin": 1, "dateMax": 200, "datation": "Ier-IIe siècle apr. J.-C., probable", "epoque": ["Antiquité"], "culture": ["Romaine"], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Moulé"], "decor": ["Géométrique"], "fonctionUsage": ["Harnachement", "Guide de rênes"], "particularites": "Anneau de harnais à grand passage circulaire, prolongé à la base par une fixation intégrée formant une ouverture longitudinale et un terminal évasé. Le dispositif de fixation est nettement plus développé que sur un simple anneau de terret.", "usageTexte": "Fixé au harnachement d’un cheval ou d’un véhicule attelé, ce terret servait à guider les rênes et à les maintenir dans une position régulière.", "texteAnalyse": "La combinaison d’un grand anneau destiné au passage des rênes et d’un dispositif basal de fixation permet d’identifier l’objet comme un terret de harnais.\n\nLa fixation intégrée, avec ouverture longitudinale et terminal évasé, correspond à des formes montées sur les courroies ou éléments du harnachement. L’objet appartient à la même famille fonctionnelle que OBJ-0041, mais avec un système de fixation plus développé.\n\nUne attribution à l’époque romaine est probable. La fourchette de travail retenue est le Ier-IIe siècle apr. J.-C., soit environ 1 à 200."}, {"id": "OBJ-0041", "designation": "Terret simple de harnais en alliage cuivreux", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0041_terrets_harnais_comparaison_OBJ-0040.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0041.jpg", "vignette": null, "nature": ["Harnachement"], "dimensions": "58 x 42 mm ; épaisseur env. 3 mm", "poids": "", "dateMin": -100, "dateMax": 100, "datation": "Fin de l’âge du Fer – début de l’époque romaine", "epoque": ["Protohistoire", "Antiquité"], "culture": [], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Moulé"], "decor": ["Géométrique", "Moulures transversales"], "fonctionUsage": ["Harnachement", "Guide de rênes"], "particularites": "Terret simple à grand anneau ovale et barre basale rectangulaire intégrée, avec moulures transversales sur la partie inférieure. Cette forme est caractéristique des terrets simples de la fin de l’âge du Fer et du début de l’époque romaine. L’objet servait de guide de rênes sur le harnachement d’un véhicule attelé. Il appartient à la même famille fonctionnelle que OBJ-0040.", "usageTexte": "", "texteAnalyse": ""}, {"id": "OBJ-0042", "designation": "Fibule romaine fortement profilée, type Almgren 70/73 probable", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/OBJ-0042_fibule_romaine_fortement_profilee_Almgren_70_73_probable.pdf", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0042.jpg", "vignette": null, "nature": ["Fibules"], "dimensions": "Longueur 75 mm ; largeur 25 mm ; hauteur env. 28 mm", "poids": "", "dateMin": 80, "dateMax": 160, "datation": "Fin du Ier - première moitié du IIe siècle apr. J.-C.", "epoque": ["Antiquité"], "culture": ["Romaine"], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux", "Fer probable"], "materiauxNonMetalliques": [], "technique": ["Moulé", "Ressort spiralé"], "decor": ["Profilé", "Moulures transversales", "Bouton terminal"], "fonctionUsage": ["Parure vestimentaire", "Fixation"], "particularites": "Grande fibule romaine fortement profilée, à arc puissant et fortement cambré. Une importante moulure annulaire marque la transition vers un long pied effilé terminé par un bouton relevé. Le porte-ardillon est développé et l’ardillon est largement conservé.", "usageTexte": "Cette fibule servait à fixer et maintenir une pièce de vêtement. Son arc massif et son profil très marqué lui donnaient également une présence ornementale importante.", "texteAnalyse": "La construction appartient au groupe des fibules romaines fortement profilées, largement diffusées dans les provinces danubiennes du monde romain. La morphologie correspond probablement aux variantes Almgren 70/73.\n\nCe groupe est caractéristique de la fin du Ier siècle et de la première moitié du IIe siècle apr. J.-C. Pour cet exemplaire, une datation de travail vers 80-160 apr. J.-C. est retenue. Son profil et sa construction s’inscrivent dans les productions romaines particulièrement bien représentées dans les régions danubiennes, notamment le Norique et la Pannonie."}, {"id": "OBJ-0043", "designation": "Boucle composite médiévale à entretoise fourchue intégrée", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0043.jpg", "vignette": null, "nature": ["Parures vestimentaires"], "dimensions": "79 x 47 mm", "poids": "", "dateMin": 1350, "dateMax": 1450, "datation": "Milieu du XIVe - milieu du XVe siècle, vers 1350-1450", "epoque": ["Moyen Âge"], "culture": [], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Moulé"], "decor": [], "fonctionUsage": ["Vie quotidienne"], "particularites": "Grande boucle composite en alliage cuivreux à cadre ovale. Le cadre se prolonge directement par deux longues branches parallèles constituant une entretoise fourchue intégrée. L’ardillon, long et légèrement courbe, est conservé. Les plaques qui enserraient à l’origine l’entretoise et maintenaient l’extrémité de la courroie ont disparu.", "usageTexte": "Cette boucle servait à fermer et régler une ceinture ou une courroie. L’extrémité de la courroie était maintenue entre deux plaques fixées de part et d’autre de l’entretoise fourchue, tandis que l’ardillon venait s’engager dans l’un des trous de la courroie.", "texteAnalyse": "La construction est caractéristique des boucles composites médiévales à entretoise fourchue intégrée. Le cadre et les deux longues branches parallèles sont conçus comme un même ensemble métallique, les branches servant de support aux plaques aujourd’hui disparues qui maintenaient la courroie.\n\nL’ardillon est encore conservé et permet de comprendre directement le fonctionnement de la boucle. Sa présence confirme que le grand cadre ovale constituait bien la partie active de fermeture.\n\nLes boucles à entretoise fourchue de ce type sont principalement attestées aux XIVe et XVe siècles. Une datation de travail vers 1350-1450 est retenue pour cet exemplaire."}, {"id": "OBJ-0044", "designation": "Fibule romaine tardive en arbalète à boutons d’oignon, type Keller 4A probable", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0044.jpg", "vignette": null, "nature": ["Fibules"], "dimensions": "70 x 26 mm", "poids": "", "dateMin": 330, "dateMax": 400, "datation": "IVe siècle apr. J.-C., probablement seconde moitié du siècle", "epoque": ["Antiquité"], "culture": ["Romaine"], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Moulé"], "decor": ["Géométrique", "Ocelles", "Boutons globulaires"], "fonctionUsage": ["Parure vestimentaire", "Fixation", "Militaire / administratif"], "particularites": "Fibule cruciforme tardive à arc fortement cintré, longue plaque de pied et barre transversale terminée par trois gros boutons globulaires caractéristiques dits boutons d’oignon. Le pied porte un décor de petits cercles ou ocelles. Le système de fixation est largement conservé.", "usageTexte": "Cette fibule servait à fixer le manteau ou la tunique et constituait également un marqueur de statut. Les fibules à boutons d’oignon sont particulièrement associées, dans l’Antiquité tardive, au costume masculin officiel, notamment dans les milieux militaires et administratifs.", "texteAnalyse": "La combinaison de l’arc fortement cintré, de la longue plaque de pied, de la barre transversale et des trois boutons globulaires permet d’identifier l’objet comme une fibule romaine tardive en arbalète à boutons d’oignon.\n\nLes proportions, la longueur de 70 mm et le décor du pied rapprochent particulièrement cet exemplaire du type Keller 4A, ou d’un groupe très voisin. Cette attribution reste probable plutôt qu’absolue en l’absence d’examen direct et de contexte archéologique.\n\nCes fibules appartiennent principalement au IVe siècle apr. J.-C. Une datation de travail vers 330-400 est retenue, avec une probabilité plus forte pour la seconde moitié du siècle. Elles sont étroitement liées au costume masculin officiel de l’Empire romain tardif et sont fréquemment associées aux milieux militaires et administratifs."}, {"id": "OBJ-0045", "designation": "Anneau de pouce d’archer à palette triangulaire gravée", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0045.jpg", "vignette": null, "nature": ["Bagues", "Objets militaires"], "dimensions": "Diamètre intérieur 22 mm ; palette triangulaire env. 20 mm", "poids": "", "dateMin": 1300, "dateMax": 1600, "datation": "XIVe-XVIe siècle, datation de travail", "epoque": ["Moyen Âge", "Renaissance"], "culture": [], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Moulé", "Incisé"], "decor": ["Géométrique", "Rayonnant", "Chevrons / hachures"], "fonctionUsage": ["Guerre"], "particularites": "Anneau de pouce massif en alliage cuivreux, de 22 mm de diamètre intérieur, prolongé sur la face externe par une large palette triangulaire. Celle-ci porte un décor entièrement non figuratif composé de lignes incisées, de faisceaux de hachures obliques, de chevrons et d’un petit motif central étoilé ou en rosette rayonnante. Le décor se prolonge sur les côtés de la palette. L’anneau est large, épais et légèrement asymétrique. Une petite protubérance extérieure est présente à l’arrière de l’anneau ; elle paraît appartenir à la construction d’origine et avoir eu un rôle fonctionnel dans le maintien ou le positionnement de l’anneau sur le pouce.", "usageTexte": "Cet anneau se portait au pouce lors du tir à l’arc avec une décoche au pouce. Il protégeait le doigt de la pression de la corde et sa large palette triangulaire formait une surface permettant de contrôler puis de libérer la corde au moment de la décoche. Ce type d’équipement pouvait être utilisé dans un contexte militaire, mais aussi pour la chasse ou l’entraînement.", "texteAnalyse": "La morphologie est caractéristique d’un anneau de pouce d’archer : anneau très large et robuste, diamètre intérieur compatible avec le pouce et forte extension triangulaire destinée à travailler au contact de la corde. Cette construction est très différente de celle d’une bague décorative ordinaire à chaton.\n\nLa face triangulaire est ornée d’un décor géométrique incisé. Le petit motif central peut être décrit comme une étoile ou une rosette rayonnante, mais rien ne permet de l’identifier avec certitude comme une représentation solaire. Les lignes obliques, chevrons et faisceaux de hachures constituent l’essentiel du décor et restent non figuratifs.\n\nLa petite protubérance située à l’arrière de l’anneau paraît intentionnelle et non accidentelle. Des anneaux d’archer présentent des excroissances ou épaississements comparables destinés à améliorer le maintien ou le positionnement sur le pouce ; sa fonction exacte sur cet exemplaire ne peut toutefois pas être déterminée sans comparaison typologique plus précise.\n\nLes anneaux de pouce d’archer métalliques de cette famille sont connus dans plusieurs régions, notamment dans les Balkans, le monde byzantin puis ottoman et plus largement dans les cultures utilisant la décoche au pouce. Sans provenance archéologique, aucune attribution culturelle ou géographique précise n’est retenue. Une datation prudente du XIVe au XVIe siècle est proposée."}, {"id": "OBJ-0046", "designation": "Bracelet ouvert protohistorique en alliage cuivreux à extrémités aplaties", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0046.jpg", "vignette": null, "nature": ["Bijoux"], "dimensions": "Diamètre extérieur 56 mm ; jonc env. 7 mm, s’amincissant jusqu’à env. 5 mm vers les extrémités", "poids": "", "dateMin": -900, "dateMax": -500, "datation": "Bronze final - premier âge du Fer, datation de travail", "epoque": ["Protohistoire"], "culture": [], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Moulé"], "decor": [], "fonctionUsage": ["Vie quotidienne"], "particularites": "Bracelet ouvert à jonc massif, circulaire à subcirculaire, sans décor visible. Le jonc atteint environ 7 mm dans sa partie la plus épaisse puis s’amincit progressivement jusqu’à environ 5 mm vers les deux extrémités. Celles-ci sont légèrement élargies et aplaties, sans motif figuratif ni traitement zoomorphe.", "usageTexte": "Ce bracelet constituait un élément de parure porté au poignet. Sa forme ouverte permettait une certaine adaptation au bras et facilitait sa mise en place.", "texteAnalyse": "La morphologie générale correspond à celle d’un bracelet ouvert protohistorique en alliage cuivreux : jonc massif, absence de décor et extrémités simples légèrement aplaties et élargies.\n\nLe diamètre extérieur de 56 mm et surtout l’évolution de la section, d’environ 7 mm dans la partie centrale à environ 5 mm près des extrémités, sont compatibles avec des bracelets ouverts du Bronze final et du premier âge du Fer.\n\nAucun élément ne justifie une interprétation zoomorphe des extrémités. En l’absence de provenance archéologique ou de décor typologique plus caractéristique, une datation prudente entre environ 900 et 500 av. J.-C. est retenue."}, {"id": "OBJ-0047", "designation": "Fibule pénannulaire de type pied d’oie, époque viking", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0047.jpg", "vignette": null, "nature": ["Fibules"], "dimensions": "53 x 38 mm ; diamètre de l’anneau env. 26 mm", "poids": "", "dateMin": 800, "dateMax": 1100, "datation": "Époque viking, IXe-XIe siècle", "epoque": ["Haut Moyen Âge"], "culture": ["Scandinave"], "aireGeographique": [], "materiauxMetalliques": ["Alliage cuivreux"], "materiauxNonMetalliques": [], "technique": ["Moulé", "Poinçonné"], "decor": ["Géométrique", "Ocelles"], "fonctionUsage": ["Parure vestimentaire", "Fixation"], "particularites": "Fibule pénannulaire en alliage cuivreux composée d’un anneau ouvert d’environ 26 mm de diamètre et de deux grands terminaux triangulaires aplatis. Les palettes sont couvertes d’un décor géométrique poinçonné composé principalement de petits cercles ou ocelles disposés en lignes. Le long ardillon est conservé et s’enroule autour de l’anneau.", "usageTexte": "Cette fibule servait à fermer et maintenir une pièce de vêtement, probablement un manteau ou une tunique. L’ardillon traversait l’étoffe puis venait se placer dans l’ouverture de l’anneau, tandis que les grands terminaux triangulaires formaient la partie décorative visible.", "texteAnalyse": "La construction permet d’identifier l’objet comme une fibule pénannulaire : anneau ouvert, ardillon mobile enroulé autour du jonc et deux grands terminaux triangulaires. Cette forme est souvent rapprochée des fibules dites de type « pied d’oie » ou Kukonjalka.\n\nLe décor est entièrement géométrique et repose principalement sur des cercles ou ocelles poinçonnés disposés sur les deux palettes triangulaires. Aucun motif figuratif n’est identifiable.\n\nCe type de fibule appartient aux traditions vestimentaires du nord et de l’est de l’Europe durant le haut Moyen Âge et se rencontre notamment dans les milieux baltiques, finno-ougriens et de la Rus’, en relation avec les réseaux de l’époque viking. Pour le classement du catalogue, la catégorie « Scandinave » est retenue comme repère pratique, sans prétendre déterminer une provenance précise. Une datation de travail du IXe au XIe siècle, soit environ 800-1100, est retenue."}, {"id": "OBJ-0048", "designation": "Bracelet en verre vert à pastilles brun-rouge appliquées", "pdf": "https://88ja88.github.io/JA-Artefacts/pdf/", "photo": "https://88ja88.github.io/JA-Artefacts/CATALOGUE/photos/OBJ-0048.jpg", "vignette": null, "nature": ["Bijoux"], "dimensions": "Diamètre environ 56 mm ; jonc environ 4 mm s’amincissant vers 2 mm", "poids": "", "dateMin": 800, "dateMax": 1500, "datation": "IXe–XVe siècles, époque islamique probable", "epoque": ["Moyen Âge"], "culture": ["Arabo-musulmane"], "aireGeographique": [], "materiauxMetalliques": [], "materiauxNonMetalliques": ["Verre"], "technique": ["Formé à chaud", "Appliqué à chaud"], "decor": ["Géométrique"], "fonctionUsage": ["Vie quotidienne"], "particularites": "Bracelet en verre vert translucide portant sur sa face extérieure une série de pastilles ovales brun-rouge régulièrement espacées et appliquées à chaud. Anneau incomplet. Altération superficielle du verre. Attribution à la période islamique médiévale probable, sans provenance géographique attestée.", "usageTexte": "", "texteAnalyse": ""}];
